# --- Précisions du locuteur (serie_04_termes, 2026-09-17) ---
serie_04:
  - {snk: beteye, fr: midi}
  - {snk: "xara-kompe", fr: école, note: "littéralement la maison où l'on apprend ; lokolou est l'emprunt courant"}
  - {snk: lemane, fr: un peu, exemple: "o na fo lemane sefe = nous parlons un peu"}
  - {snk: xoto, fr: difficile}
  - {snk: siri, fr: "bien (bien fait)"}
  - {snk: sarano, fr: "les parents (père et mère)"}
  - {snk: bara, fr: "cour, espace"}
  - {snk: "-su", fr: "chaque / tout", exemple: "suxuba-su, lele-su, sere-su"}
  - {snk: "-ni", fr: "pluriel", exemple: "maro-ni = les riz"}
  - {snk: "m'fallaqe", fr: derrière, note: "corrigé : derrière, et non devant ; proche de m'falle (après)"}
  - {snk: "do me", fr: "ensemble", note: "o na tere do me, o na yige do me, o na xara do me"}
  - {snk: "o ya / oku ya", fr: "à nous"}
  - {snk: possessifs, fr: "n, an, a, o, xa, i + nom", exemple: "a ka = sa maison, i yiramu = leurs vêtements"}
  - {snk: na, fr: "présent (on explique ce qu'on fait)", exemple: "nke na wutu = je prends ; nke di wutu = je l'ai déjà pris"}
