texte_5_suite:
  - {snk: "ado", fr: "et", exemple: "maro ado xati = du riz et du lait"}
  - {snk: "ado na", fr: "et (entre deux ordres)", exemple: "kitabe ke wutu ado na xara = prends le livre et lis-le"}
  - {snk: yeli, fr: "viens (impératif de ri)", note: "confirmé ; « yali » était une faute de frappe"}
