packages/snk-engine/src/snk_engine/conju:
"""Moteur de conjugaison soninké, piloté par les données de data/grammaire/.

Résolution d'une forme : sujet + marqueur du temps (s'il existe) + forme verbale.
La forme verbale est cherchée dans cet ordre, au niveau du verbe puis de sa classe :

  1. forme propre au sujet     (conjugaison.<temps>.formes.<sujet>
                                ou conjugaison.<temps>.exceptions.<sujet>)
  2. forme propre au temps     (conjugaison.<temps>.forme)
  3. forme du verbe            (forme)

Dans une forme, « {forme} » est remplacé par la forme du verbe et « {gerondif} »
par son gérondif (forme en -nV : dagana, rini).

Objet : un temps marqué `objet: true` place l'objet entre le marqueur et le verbe
(ake n'di maro n'yiga) ; le verbe prend alors sa `forme_objet` si elle est connue.

Particule (section `particules`) : pour un temps marqué `particule: true` et un sujet
listé dans `particules.personnes`, elle se colle au premier mot qui suit le sujet
(marqueur ou verbe) et dépend de l'initiale de ce mot : aké n'daga, aké n'yi rini daga.

Le moteur n'applique aucune règle implicite : un verbe sans conjugaison, un temps
non renseigné ou une personne absente de `personnes` lèvent une erreur.
"""

from __future__ import annotations

import unicodedata
from dataclasses import dataclass, field
from functools import lru_cache
from pathlib import Path

import yaml

def _find_grammar() -> Path:
    """Remonte jusqu'au dossier data/grammaire du dépôt (le code peut être déplacé)."""
    for parent in Path(__file__).resolve().parents:
        candidate = parent / "data" / "grammaire"
        if candidate.is_dir():
            return candidate
    return Path("data/grammaire")


DEFAULT_GRAMMAR = _find_grammar()
DATA_DIR = DEFAULT_GRAMMAR.parent


class ConjugationError(Exception):
    pass


class UnknownVerbError(ConjugationError):
    pass


class UnknownSubjectError(ConjugationError):
    pass


class UnknownTenseError(ConjugationError):
    pass


class ConjugationNotDefinedError(ConjugationError):
    pass


def _nfc(text: str) -> str:
    return unicodedata.normalize("NFC", text)


@dataclass(frozen=True)
class Pronoun:
    form: str
    person: str
    french: str
    series: str | None = None


@dataclass(frozen=True)
class Tense:
    name: str
    label: str
    marker: str | None = None
    particle: bool = False
    suffix: str | None = None   # placé après le verbe
    object: bool = False        # un objet se place entre le marqueur et le verbe
    verb_particle: bool = False # le verbe qui suit l'objet prend aussi la particule
    no_subject: bool = False    # l'impératif ne montre pas son sujet


@dataclass(frozen=True)
class ParticleRule:
    """Particule placée devant le mot qui suit le sujet, choisie d'après son initiale."""

    persons: frozenset[str] = frozenset()
    by_initial: dict[str, str] = field(default_factory=dict)
    default: str | None = None
    unconfirmed: frozenset[str] = frozenset()


@dataclass(frozen=True)
class TenseRule:
    """Formes confirmées d'un verbe (ou d'une classe) pour un temps."""

    persons: frozenset[str] = frozenset()
    form: str | None = None
    exceptions: dict[str, str] = field(default_factory=dict)
    notes: str | None = None


@dataclass(frozen=True)
class ConjugationClass:
    name: str
    rules: dict[str, TenseRule] = field(default_factory=dict)


@dataclass(frozen=True)
class Verb:
    infinitive: str
    french: str
    form: str | None = None
    conjugation_class: str | None = None
    rules: dict[str, TenseRule] = field(default_factory=dict)
    gerund: str | None = None      # forme en -nV (dagana, rini)
    object_form: str | None = None # forme du verbe quand il a un objet (yiga)
    object_gerund: str | None = None # forme en -ni de la forme à objet (yigane)
    action_noun: str | None = None   # nom d'action : yigaye, dagaye
    transitive: bool = False       # le verbe accepte un objet (confirmé)


class ConjugationEngine:
    def __init__(
        self,
        pronouns: list[Pronoun],
        tenses: dict[str, Tense],
        verbs: dict[str, Verb],
        classes: dict[str, ConjugationClass] | None = None,
        particles: ParticleRule | None = None,
    ) -> None:
        self.pronouns: dict[str, list[Pronoun]] = {}
        for p in pronouns:
            self.pronouns.setdefault(p.form, []).append(p)
        self.tenses = tenses
        self.verbs = verbs
        self.classes = classes or {}
        self.particles = particles or ParticleRule()
        self._check()

    def _check(self) -> None:
        for v in self.verbs.values():
            if v.conjugation_class and v.conjugation_class not in self.classes:
                raise ConjugationError(f"Classe inconnue '{v.conjugation_class}' pour le verbe '{v.infinitive}'")
        owners = [(v.infinitive, v.rules) for v in self.verbs.values()]
        owners += [(f"classe {c.name}", c.rules) for c in self.classes.values()]
        for owner, rules in owners:
            for tense, rule in rules.items():
                if tense not in self.tenses:
                    raise ConjugationError(f"Temps inconnu '{tense}' dans {owner}")
                for subject in rule.persons | rule.exceptions.keys():
                    if subject not in self.pronouns:
                        raise ConjugationError(f"Sujet inconnu '{subject}' dans {owner} ({tense})")
        for subject in self.particles.persons - self.pronouns.keys():
            raise ConjugationError(f"Sujet inconnu '{subject}' dans particules")

    def _rules(self, verb: Verb, tense: str) -> list[TenseRule]:
        rules = [verb.rules[tense]] if tense in verb.rules else []
        cls = self.classes.get(verb.conjugation_class or "")
        if cls and tense in cls.rules:
            rules.append(cls.rules[tense])
        return rules

    def particle(self, form: str) -> str:
        """Particule à placer devant le mot `form` (ex. daga → n')."""
        initial = _nfc(form)[:1].lower()
        if not initial:
            raise ConjugationNotDefinedError("Forme vide : particule indéterminable")
        if initial in self.particles.by_initial:
            return self.particles.by_initial[initial]
        if initial in self.particles.unconfirmed or self.particles.default is None:
            raise ConjugationNotDefinedError(f"Particle not confirmed for initial '{initial}' ('{form}')")
        return self.particles.default

    def is_conjugable(self, verb: str) -> bool:
        v = self.verbs.get(_nfc(verb))
        return bool(v and (v.rules or v.conjugation_class))

    def conjugate(self, verb: str, subject: str, tense: str, obj: str | None = None) -> str:
        predicate = self.predicate(verb, subject, tense, obj)
        if tense in self.tenses and self.tenses[tense].no_subject:
            return predicate
        return f"{_nfc(subject)} {predicate}"

    def predicate(self, verb: str, subject: str, tense: str, obj: str | None = None) -> str:
        """Tout ce qui suit le sujet : particule + marqueur (+ objet) + forme verbale."""
        subject = _nfc(subject)
        t = self.tenses[tense] if tense in self.tenses else None
        if t is not None:
            if t.object and obj is None:
                raise ConjugationNotDefinedError(f"Le temps '{tense}' demande un objet")
            if obj is not None and not t.object:
                raise ConjugationNotDefinedError(f"Le temps '{tense}' ne prend pas d'objet")
        form = self.verb_form(verb, subject, tense, obj is not None)
        t = self.tenses[tense]
        if t.verb_particle:
            form = self.particle(form) + form
        words = " ".join(p for p in (t.marker, _nfc(obj) if obj else None, form, t.suffix) if p)
        if t.particle and subject in self.particles.persons:
            words = self.particle(words) + words
        return words

    def verb_form(self, verb: str, subject: str, tense: str, with_object: bool = False) -> str:
        """Forme verbale seule, sans sujet ni marqueur de temps."""
        verb, subject = _nfc(verb), _nfc(subject)
        v = self.verbs.get(verb)
        if v is None:
            raise UnknownVerbError(f"Verbe inconnu : '{verb}'")
        if subject not in self.pronouns:
            raise UnknownSubjectError(f"Sujet inconnu : '{subject}'")
        if tense not in self.tenses:
            raise UnknownTenseError(f"Temps inconnu : '{tense}'")
        if not self.is_conjugable(verb):
            raise ConjugationNotDefinedError(f"Conjugation rule not defined for verb '{verb}'")

        rules = self._rules(v, tense)
        if not rules:
            raise ConjugationNotDefinedError(f"Conjugation rule not defined for verb '{verb}' in tense '{tense}'")
        if not any(subject in r.persons for r in rules):
            raise ConjugationNotDefinedError(
                f"Form not confirmed for verb '{verb}', subject '{subject}', tense '{tense}'"
            )

        if with_object and v.object_form and not any("{" in (r.form or "") for r in rules):
            return v.object_form
        form = next((r.exceptions[subject] for r in rules if subject in r.exceptions), None)
        if form is None:  # forme vide "" permise : le marqueur suffit (ex. okou yi rini)
            form = next((r.form for r in rules if r.form is not None), v.form)
        if form is None:
            raise ConjugationNotDefinedError(f"No verb form defined for '{verb}' in tense '{tense}'")
        for placeholder, value in (("{forme}", v.form), ("{gerondif_objet}", v.object_gerund),
                                   ("{gerondif}", v.gerund), ("{nom_action}", v.action_noun)):
            if placeholder in form:
                if value is None:
                    raise ConjugationNotDefinedError(f"Verb '{verb}' has no value for '{placeholder}'")
                form = form.replace(placeholder, value)
        return form

    @classmethod
    def from_paths(cls, paths: list[Path]) -> "ConjugationEngine":
        data: dict = {"pronoms": [], "temps": {}, "classes": {}, "verbes": {}, "particules": {}}
        for path in _yaml_files(paths):
            content = yaml.safe_load(_nfc(path.read_text(encoding="utf-8"))) or {}
            data["pronoms"] += content.get("pronoms") or []
            for key in ("temps", "classes", "verbes", "particules"):
                section = content.get(key) or {}
                if dup := data[key].keys() & section.keys():
                    raise ConjugationError(f"{key} définis plusieurs fois ({path.name}) : {sorted(dup)}")
                data[key].update(section)

        pronouns = [Pronoun(p["forme"], p["personne"], p["fr"], p.get("serie")) for p in data["pronoms"]]
        tenses = {
            name: Tense(name, t.get("nom", name), t.get("marqueur"), bool(t.get("particule")),
                        t.get("suffixe"), bool(t.get("objet")), bool(t.get("particule_verbe")),
                        bool(t.get("sans_sujet")))
            for name, t in data["temps"].items()
        }
        classes = {
            name: ConjugationClass(name, _parse_rules((c or {}).get("conjugaison")))
            for name, c in data["classes"].items()
        }
        verbs = {
            inf: Verb(
                infinitive=inf,
                french=v["fr"],
                form=v.get("forme"),
                conjugation_class=v.get("classe"),
                rules=_parse_rules(v.get("conjugaison")),
                gerund=v.get("gerondif"),
                object_form=v.get("forme_objet"),
                object_gerund=v.get("gerondif_objet"),
                action_noun=v.get("nom_action"),
                transitive=bool(v.get("transitif")),
            )
            for inf, v in data["verbes"].items()
        }
        part = data["particules"]
        particles = ParticleRule(
            persons=frozenset(_nfc(x) for x in part.get("personnes") or []),
            by_initial={_nfc(k).lower(): v for k, v in (part.get("par_initiale") or {}).items()},
            default=part.get("defaut"),
            unconfirmed=frozenset(_nfc(k).lower() for k in part.get("a_confirmer") or []),
        )
        return cls(pronouns, tenses, verbs, classes, particles)


def _parse_rules(raw: dict | None) -> dict[str, TenseRule]:
    rules: dict[str, TenseRule] = {}
    for tense, r in (raw or {}).items():
        r = r or {}
        by_subject = {**(r.get("exceptions") or {}), **(r.get("formes") or {})}
        rules[tense] = TenseRule(
            persons=frozenset(r.get("personnes") or []) | frozenset(r.get("formes") or {}),
            form=r.get("forme"),
            exceptions=by_subject,
            notes=r.get("remarques"),
        )
    return rules


def _yaml_files(paths: list[Path]) -> list[Path]:
    files: list[Path] = []
    for p in paths:
        files.extend(sorted(p.rglob("*.y*ml")) if p.is_dir() else [p])
    return files


@lru_cache(maxsize=1)
def default_engine() -> ConjugationEngine:
    return ConjugationEngine.from_paths([DEFAULT_GRAMMAR])


def conjugate(verb: str, subject: str, tense: str) -> str:
    return default_engine().conjugate(verb, subject, tense)

packages/snk-engine/src/snk_engine/frenc:
"""Côté français des phrases : conjugaison minimale, pilotée par les données.

Chaque verbe porte dans data/grammaire/soninke.yaml une section `francais` :
auxiliaire (avoir/etre), participe, present[6], imparfait[6], futur_radical.
Les six formes sont dans l'ordre : je, tu, il, nous, vous, ils.
"""

from __future__ import annotations

from dataclasses import dataclass

PERSONS = ["1sg", "2sg", "3sg", "1pl", "2pl", "3pl"]
SUBJECTS = {"1sg": "je", "2sg": "tu", "3sg": "il", "1pl": "nous", "2pl": "vous", "3pl": "ils"}
AUX = {
    "avoir": ["ai", "as", "a", "avons", "avez", "ont"],
    "etre": ["suis", "es", "est", "sommes", "êtes", "sont"],
}
FUTURE_ENDINGS = ["ai", "as", "a", "ons", "ez", "ont"]
PLURAL = {"1pl", "2pl", "3pl"}
IMPERATIVE_SLOTS = {"2sg": 0, "1pl": 1, "2pl": 2}


class FrenchError(ValueError):
    pass


@dataclass(frozen=True)
class FrenchVerb:
    infinitive: str          # clé du verbe soninké
    french_infinitive: str
    aux: str
    participle: str
    present: list[str]
    imperfect: list[str]
    future_stem: str
    subjunctive: list[str] | None = None
    imperative: list[str] | None = None   # tu, nous, vous

    @classmethod
    def from_data(cls, infinitive: str, data: dict) -> "FrenchVerb":
        try:
            return cls(infinitive, data.get("infinitif", ""), data["auxiliaire"], data["participe"],
                       list(data["present"]), list(data["imparfait"]), data["futur_radical"],
                       list(data["subjonctif"]) if data.get("subjonctif") else None,
                       list(data["imperatif"]) if data.get("imperatif") else None)
        except KeyError as exc:
            raise FrenchError(f"Formes françaises incomplètes pour '{infinitive}' : {exc}") from exc


def _elide(subject: str, word: str) -> str:
    """je + ai → j'ai."""
    if subject == "je" and word[:1].lower() in "aeiouéèêh":
        return f"j'{word}"
    return f"{subject} {word}"


def _negate(subject: str, first: str, rest: str) -> str:
    ne = "n'" if first[:1].lower() in "aeiouéèêh" else "ne "
    head = "j'" + first if subject == "je" and ne == "n'" else f"{subject} {ne}{first}"
    if subject == "je" and ne == "n'":
        head = f"je n'{first}"
    return f"{head} pas {rest}".strip()


def conjugate_fr(verb: FrenchVerb, person: str, tense: str, obj: str | None = None) -> str:
    """Phrase française correspondant au temps soninké `tense`."""
    if person not in PERSONS:
        raise FrenchError(f"Personne inconnue : {person}")
    i = PERSONS.index(person)
    subject = SUBJECTS[person]
    participle = verb.participle
    if verb.aux == "etre" and person in PLURAL:
        participle += "s"
    compose = f"{AUX[verb.aux][i]} {participle}"
    future = verb.future_stem + FUTURE_ENDINGS[i]
    tail = f" {obj}" if obj else ""

    if tense in ("past", "past_object"):
        return _elide(subject, compose) + tail
    if tense in ("imperatif", "imperatif_objet", "imperatif_pluriel", "imperatif_negatif"):
        if not verb.imperative:
            raise FrenchError(f"Pas d'impératif français pour '{verb.infinitive}'")
        form = verb.imperative[2 if tense == "imperatif_pluriel" else 0]
        if tense == "imperatif_negatif":
            return f"ne {form} pas"
        return form + tail

    if tense in ("demande", "demande_objet"):
        # « na » exprime une demande : l'impératif quand le français l'a, sinon « que… »
        if person in IMPERATIVE_SLOTS and verb.imperative:
            return verb.imperative[IMPERATIVE_SLOTS[person]] + tail
        if not verb.subjunctive:
            raise FrenchError(f"Pas de subjonctif français pour '{verb.infinitive}'")
        que = "qu'" if subject.startswith(("il", "el")) else "que "
        return f"{que}{subject} {verb.subjunctive[i]}{tail}"
    if tense in ("en_cours_do", "en_cours_objet_do"):
        return _elide(subject, f"{AUX['etre'][i]} en train de {verb.french_infinitive}") + tail
    if tense in ("en_cours_objet", "en_cours_objet_fayi"):
        return _elide(subject, verb.present[i]) + tail
    if tense in ("en_cours", "en_cours_fayi"):
        # présent simple : « en ce moment » entrerait en conflit avec « koota su »
        return _elide(subject, verb.present[i]) + tail
    if tense == "imperfect":
        return _elide(subject, verb.imperfect[i]) + tail
    if tense == "imminent":
        return _elide(subject, f"{AUX['etre'][i]} sur le point de {verb.french_infinitive}") + tail
    if tense == "progressive_watia":
        return _elide(subject, f"{AUX['etre'][i]} en train de {verb.french_infinitive}") + tail
    if tense == "future":
        return _elide(subject, future) + tail
    if tense == "past_negative":
        return _negate(subject, AUX[verb.aux][i], f"{participle}{tail}")
    if tense in ("future_negative", "future_negative_ntaxa"):
        return _negate(subject, future, tail.strip())
    raise FrenchError(f"Temps sans traduction française : '{tense}'")

packages/snk-engine/src/snk_engine/ortho:
"""Normalisation et validation orthographique.

L'alphabet est configurable (configs/default.yaml → orthographe.alphabet)
pour s'adapter à la norme retenue (Mali, Sénégal, Mauritanie, Gambie).
"""

from __future__ import annotations

import re
import unicodedata

_SPACES = re.compile(r"\s+")
_SPACE_BEFORE_PUNCT = re.compile(r"\s+([.,;:!?])")


def normalize(text: str, capitalize: bool = True, final_punct: str | None = ".") -> str:
    text = unicodedata.normalize("NFC", text)
    text = _SPACES.sub(" ", text).strip()
    text = _SPACE_BEFORE_PUNCT.sub(r"\1", text)
    if not text:
        return text
    if capitalize:
        text = text[0].upper() + text[1:]
    if final_punct and text[-1] not in ".!?":
        text += final_punct
    return text


_GU = re.compile(r"(?<=[gG])u(?=[eéèiíì])")


def modernize(text: str) -> str:
    """Ancienne notation du projet → orthographe confirmée (x, u, e, g).

    kh → x, ou → u, é → e, gu devant e/i → g. Ne touche ni aux apostrophes
    ni aux traits d'union du gérondif, qui ne se déduisent pas.
    """
    text = unicodedata.normalize("NFC", text)
    text = text.replace("kh", "x").replace("Kh", "X")
    text = _GU.sub("", text)
    text = text.replace("ou", "u").replace("Ou", "U")
    return text.replace("é", "e").replace("É", "E")


class Orthography:
    def __init__(self, alphabet: str, extra: str = " '-.,;:!?") -> None:
        letters = unicodedata.normalize("NFC", alphabet)
        self.allowed = set(letters.lower()) | set(letters.upper()) | set(extra)

    def invalid_chars(self, text: str) -> set[str]:
        return {c for c in unicodedata.normalize("NFC", text) if c not in self.allowed}

    def is_valid(self, text: str) -> bool:
        return not self.invalid_chars(text)

packages/snk-engine/src/snk_engine/trans:
"""Traduire du français vers le soninké.

Le principe est symétrique de understand.py, et tout aussi prudent :

  1. **reconnaître le verbe** : le moteur sait produire le français de chaque verbe
     confirmé, à chaque personne et à chaque temps (conjugate_fr). On en construit
     l'index inverse — « il a mangé » → (yigeyer, 3sg, past) ;
  2. **reconnaître le reste** : ce qui suit le verbe est cherché dans le glossaire
     inversé (objets et compléments confirmés d'abord, lexique ensuite) ;
  3. **produire le soninké** avec le moteur de conjugaison lui-même.

Rien n'est deviné : un passage français qu'aucune donnée ne couvre devient [unknown].
"""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass

from .conjugation import ConjugationError
from .french import PERSONS, FrenchError, conjugate_fr
from .understand import UNKNOWN, Lexicon, collapse_unknowns, load_lexicon

SENTENCE_SPLIT = re.compile(r"(?<=[.!?])\s+")
CLAUSE_SPLIT = re.compile(r"\s*([,;:])\s*")

# Quand plusieurs temps donnent le même français, on préfère le plus courant.
TENSE_PREFERENCE = [
    "past", "past_object", "en_cours", "en_cours_objet", "future", "past_negative",
    "future_negative", "imperatif", "imperatif_objet", "imperatif_negatif",
    "imperatif_pluriel", "demande", "demande_objet", "imminent", "en_cours_do",
    "en_cours_objet_do", "progressive_watia", "en_cours_fayi", "en_cours_objet_fayi",
    "future_negative_ntaxa",
]
WITH_OBJECT = {"past": "past_object", "en_cours": "en_cours_objet", "demande": "demande_objet",
               "imperatif": "imperatif_objet", "en_cours_fayi": "en_cours_objet_fayi",
               "en_cours_do": "en_cours_objet_do"}
SUBJECT_ALIASES = {"elle": "il", "elles": "ils", "on": "nous"}


@dataclass(frozen=True)
class Translation:
    fr: str
    snk: str
    confirme: bool
    frame: dict
    notes: tuple[str, ...] = ()
    ponctuation: str = ""


def _norm(text: str) -> str:
    text = unicodedata.normalize("NFC", text).lower().replace("’", "'")
    text = re.sub(r"\b(elles?|on)\b", lambda m: SUBJECT_ALIASES[m.group(1)], text)
    return re.sub(r"\s+", " ", text.strip(" .!?")).strip()


def build_index(lex: Lexicon) -> dict[str, list[tuple[str, str, str]]]:
    """Français produit par le moteur → [(verbe, personne, temps)]."""
    index: dict[str, list[tuple[str, str, str]]] = {}
    for verb, fr_verb in lex.french.items():
        for tense in lex.engine.tenses:
            if lex.engine.tenses[tense].object:
                continue            # les variantes à objet se retrouvent via WITH_OBJECT
            for person in PERSONS:
                try:
                    phrase = conjugate_fr(fr_verb, person, tense)
                except FrenchError:
                    continue
                index.setdefault(_norm(phrase), []).append((verb, person, tense))
    for entries in index.values():
        entries.sort(key=lambda e: TENSE_PREFERENCE.index(e[2]) if e[2] in TENSE_PREFERENCE else 99)
    return index


def reverse_glossary(lex: Lexicon) -> dict[str, str]:
    """Français → soninké ; le glossaire est déjà ordonné : confirmé d'abord."""
    out: dict[str, str] = {}
    for snk, fr in lex.glossary.items():
        out.setdefault(_norm(fr), snk)
    return out


def _match_phrases(words: list[str], glossary: dict[str, str], notes: list[str]) -> list[str]:
    """Découpe le reste de la phrase en expressions connues, la plus longue d'abord."""
    out, i = [], 0
    while i < len(words):
        for j in range(len(words), i, -1):
            chunk = " ".join(words[i:j])
            if chunk in glossary:
                out.append(glossary[chunk])
                i = j
                break
        else:
            notes.append(f"« {words[i]} » : non reconnu → {UNKNOWN}")
            out.append(UNKNOWN)
            i += 1
    return out


def _pronoun_for(lex: Lexicon, verb: str, person: str, tense: str, obj: str | None) -> str | None:
    """Premier pronom de cette personne pour lequel le moteur confirme la forme."""
    for form, pronouns in lex.engine.pronouns.items():
        if pronouns[0].person != person:
            continue
        try:
            lex.engine.conjugate(verb, form, tense, obj)
            return form
        except ConjugationError:
            continue
    return None


def translate_clause(clause: str, lex: Lexicon, index=None, glossary=None) -> Translation:
    index = index if index is not None else build_index(lex)
    glossary = glossary if glossary is not None else reverse_glossary(lex)
    notes: list[str] = []
    text = _norm(clause)
    words = text.split()

    # 1. le verbe conjugué : la plus longue expression connue en tête de phrase
    for cut in range(len(words), 0, -1):
        head = " ".join(words[:cut])
        if head not in index:
            continue
        for verb, person, tense in index[head]:
            rest = words[cut:]
            parts = _match_phrases(rest, glossary, notes)
            obj, complements = None, parts
            # un objet juste après le verbe → variante « avec objet » du temps
            if parts and parts[0] != UNKNOWN and lex.engine.verbs[verb].transitive and tense in WITH_OBJECT:
                obj_tense = WITH_OBJECT[tense]
                pronoun = _pronoun_for(lex, verb, person, obj_tense, parts[0])
                if pronoun:
                    obj, tense, complements = parts[0], obj_tense, parts[1:]
            pronoun = _pronoun_for(lex, verb, person, tense, obj)
            if pronoun is None:
                continue
            snk = " ".join([lex.engine.conjugate(verb, pronoun, tense, obj), *complements])
            snk = collapse_unknowns(snk)
            frame = {"verbe": verb, "personne": person, "temps": tense, "objet": obj,
                     "complements": complements, "pronom": pronoun}
            return Translation(clause.strip(), snk, UNKNOWN not in snk, frame, tuple(notes))

    # 2. aucun verbe reconnu : mot à mot, avec [unknown] pour le reste
    notes.append("aucun verbe reconnu : traduction mot à mot")
    snk = collapse_unknowns(" ".join(_match_phrases(words, glossary, notes)))
    return Translation(clause.strip(), snk, False, {}, tuple(notes))


def translate_text(text: str, lex: Lexicon | None = None) -> list[Translation]:
    """Traduit n'importe quel texte français, sans jamais échouer."""
    lex = lex or load_lexicon()
    index, glossary = build_index(lex), reverse_glossary(lex)
    results = []
    for sentence in (s.strip() for s in SENTENCE_SPLIT.split(text.strip()) if s.strip()):
        end = sentence[-1] if sentence[-1] in ".!?" else ""
        parts = CLAUSE_SPLIT.split(sentence.rstrip(".!?").strip())
        for i in range(0, len(parts), 2):
            if not parts[i].strip():
                continue
            punct = parts[i + 1] if i + 1 < len(parts) else end
            t = translate_clause(parts[i], lex, index, glossary)
            results.append(Translation(t.fr, t.snk, t.confirme, t.frame, t.notes, punct))
    return results


def render(translations: list[Translation]) -> str:
    out = " ".join(t.snk + t.ponctuation for t in translations)
    return re.sub(r"\s+([,;:.!?])", r"\1", out).strip()

packages/snk-engine/src/snk_engine/under:
"""Comprendre une phrase soninké et la traduire en français.

C'est le sens inverse du reste du moteur : au lieu de produire une phrase à partir
de règles, on part du texte et on cherche ce qu'il contient. L'analyse se fait en
trois étapes, comme un compilateur :

  1. **segmentation** — phrases, puis mots ; la particule collée (n', m', l', ŋ', q')
     est détachée du mot qu'elle accentue ;
  2. **tagage** — chaque mot reçoit toutes les catégories possibles (pronom,
     déterminant, marqueur de temps, verbe, mot interrogatif, mot du lexique) ;
  3. **assemblage** — les catégories sont replacées dans l'ordre confirmé par la
     grammaire : sujet – marqueur – objet – verbe – compléments.

Rien n'est deviné. Un mot qu'aucune donnée ne couvre reste tel quel côté soninké et
devient le mot littéral « unknown » côté français, avec une note qui dit lequel.
"""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass, field
from pathlib import Path

import yaml

from .conjugation import DATA_DIR, ConjugationEngine, ConjugationError, default_engine
from .french import PERSONS, SUBJECTS, FrenchError, FrenchVerb, conjugate_fr
from .orthography import modernize

UNKNOWN = "[unknown]"
PARTICLES = ("n'", "m'", "l'", "ŋ'", "q'")
SENTENCE_SPLIT = re.compile(r"(?<=[.!?])\s+")
CLAUSE_SPLIT = re.compile(r"\s*([,;:])\s*")
PUNCTUATION = "…,;:.!?«»\"()"

# Mots interrogatifs confirmés (docs/langue/questions.md)
QUESTION_WORDS = {
    "minna": "où", "xa": "où", "mane-ni": "pourquoi", "mane": "quoi", "ko": "qui",
    "kan dimma": "quand", "mani-me": "combien", "moxo": "comment", "ba": "(question)",
}


class AnalysisError(ValueError):
    """Rien n'a pu être identifié dans la phrase."""


@dataclass(frozen=True)
class Token:
    index: int
    raw: str          # tel qu'écrit, ponctuation retirée
    word: str         # sans la particule, en orthographe du projet
    particle: str | None = None
    tags: tuple[str, ...] = ()


@dataclass(frozen=True)
class Analysis:
    snk: str
    fr: str
    confirme: bool
    frame: dict
    notes: tuple[str, ...] = ()
    tokens: tuple[Token, ...] = ()
    ponctuation: str = ""   # ce qui suivait la proposition dans le texte (, ; : . ? !)


# --- Les données, lues une fois -------------------------------------------------

@dataclass(frozen=True)
class Lexicon:
    engine: ConjugationEngine
    verbs: dict[str, tuple[str, str]]        # forme → (clé du verbe, quel champ)
    reference_verbs: dict[str, str]          # radical → sens, non confirmés
    markers: dict[str, tuple[str, ...]]      # marqueur → temps possibles
    glossary: dict[str, str]                 # mot soninké → français
    french: dict[str, FrenchVerb] = field(default_factory=dict)


def _clean(word: str) -> str:
    return unicodedata.normalize("NFC", word).strip(PUNCTUATION).strip()


def _key(word: str) -> str:
    """Forme de comparaison : orthographe du projet, sans majuscule."""
    return modernize(_clean(word)).lower()


def _simple_meaning(snk, fr) -> bool:
    """Écarte les entrées ambiguës : « ? », parenthèses, plusieurs sens séparés par /."""
    if not isinstance(snk, str) or not isinstance(fr, str) or not snk or not fr:
        return False
    return not any(c in fr for c in "?(/") and "…" not in snk and "?" not in snk


def _walk_words(node) -> list[dict]:
    """Aplati data/references/mots.yaml, dont la structure varie selon les thèmes."""
    found: list[dict] = []
    if isinstance(node, dict):
        if "snk" in node:
            found.append(node)
        else:
            for value in node.values():
                found += _walk_words(value)
    elif isinstance(node, list):
        for item in node:
            found += _walk_words(item)
    return found


def load_lexicon(engine: ConjugationEngine | None = None, data_dir: Path | None = None) -> Lexicon:
    engine = engine or default_engine()
    data_dir = data_dir or DATA_DIR

    verbs: dict[str, tuple[str, str]] = {}
    for name, verb in engine.verbs.items():
        for field_name, form in (("forme", verb.form), ("gerondif", verb.gerund),
                                 ("forme_objet", verb.object_form),
                                 ("gerondif_objet", verb.object_gerund),
                                 ("nom_action", verb.action_noun)):
            if form:
                verbs.setdefault(_key(form), (name, field_name))

    # verbes du locuteur, pas encore confirmés ; la section `sources` est écartée
    reference: dict[str, str] = {}
    ref_path = data_dir / "references" / "verbes.yaml"
    if ref_path.exists():
        data = yaml.safe_load(ref_path.read_text(encoding="utf-8")) or {}
        for item in data.get("locuteur") or []:
            radical, sens = item.get("radical"), item.get("fr")
            if radical and sens and radical != "?" and "?" not in sens:
                reference.setdefault(_key(radical), sens)

    markers: dict[str, list[str]] = {}
    for name, tense in engine.tenses.items():
        if tense.marker:
            markers.setdefault(_key(tense.marker), []).append(name)

    glossary: dict[str, str] = {}
    objects_path = data_dir / "grammaire" / "objets.yaml"
    if objects_path.exists():
        data = yaml.safe_load(objects_path.read_text(encoding="utf-8")) or {}
        for item in (data.get("objets") or []) + (data.get("complements") or []):
            if _simple_meaning(item.get("snk"), item.get("fr")):
                glossary.setdefault(_key(item["snk"]), item["fr"])
    words_path = data_dir / "references" / "mots.yaml"
    if words_path.exists():
        data = yaml.safe_load(words_path.read_text(encoding="utf-8")) or {}
        for item in _walk_words(data):
            if _simple_meaning(item.get("snk"), item.get("fr")):
                glossary.setdefault(_key(item["snk"]), item["fr"])

    french: dict[str, FrenchVerb] = {}
    raw = yaml.safe_load((data_dir / "grammaire" / "soninke.yaml").read_text(encoding="utf-8")) or {}
    for name, verb in (raw.get("verbes") or {}).items():
        if verb.get("francais"):
            french[name] = FrenchVerb.from_data(name, verb["francais"])

    return Lexicon(engine, verbs, reference, {k: tuple(v) for k, v in markers.items()}, glossary, french)


# --- Étape 1 : segmentation -----------------------------------------------------

def split_sentences(text: str) -> list[str]:
    return [s.strip() for s in SENTENCE_SPLIT.split(text.strip()) if s.strip()]


def tokenize(sentence: str) -> list[Token]:
    tokens = []
    for i, raw in enumerate(w for w in sentence.split() if _clean(w)):
        word = _clean(raw)
        particle = next((p for p in PARTICLES if word.lower().startswith(p) and len(word) > len(p)), None)
        tokens.append(Token(i, word, word[len(particle):] if particle else word, particle))
    return tokens


# --- Étape 2 : tagage -----------------------------------------------------------

def tag(tokens: list[Token], lex: Lexicon) -> list[Token]:
    """Donne à chaque mot toutes ses catégories possibles ; l'assemblage tranchera."""
    tagged = []
    for token in tokens:
        key = _key(token.word)
        tags = []
        if key in lex.engine.pronouns:
            tags.append("pronom")
        if key in ("ke", "ku"):
            tags.append("determinant")
        if key in lex.markers:
            tags.append("marqueur")
        if key in lex.verbs:
            tags.append("verbe")
        elif key in lex.reference_verbs:
            tags.append("verbe_reference")
        if key in QUESTION_WORDS:
            tags.append("interrogatif")
        if key in lex.glossary:
            tags.append("lexique")
        tagged.append(Token(token.index, token.raw, token.word, token.particle, tuple(tags)))
    return tagged


def _marker_at(tokens: list[Token], i: int, lex: Lexicon) -> tuple[str, tuple[str, ...], int] | None:
    """Marqueur d'un ou deux mots à partir de la position i (« yi rini », « n'ti rini »)."""
    for length in (2, 1):
        if i + length > len(tokens):
            continue
        for use_raw in (True, False):
            text = " ".join((t.raw if use_raw else t.word) for t in tokens[i:i + length])
            tenses = lex.markers.get(_key(text))
            if tenses:
                return _key(text), tenses, length
    return None


# --- Étape 3 : assemblage -------------------------------------------------------

def assemble(tokens: list[Token], lex: Lexicon) -> tuple[dict, list[str]]:
    notes: list[str] = []
    frame: dict = {"sujet": None, "personne": None, "temps": None, "objet": None,
                   "verbe": None, "verbe_confirme": False, "forme_verbe": None,
                   "complements": [], "question": None}
    i = 0

    # 1. sujet : un pronom en tête de phrase
    if tokens and "pronom" in tokens[0].tags:
        pronoun = _key(tokens[0].word)
        if pronoun == "xa" and len(tokens) > 1:
            notes.append("« xa » en tête : lu comme le pronom « vous » (il peut aussi vouloir dire « où »)")
        frame["sujet"] = pronoun
        frame["personne"] = lex.engine.pronouns[pronoun][0].person
        i = 1

    # 2. marqueur de temps
    candidates: tuple[str, ...] = ()
    found = _marker_at(tokens, i, lex)
    if found:
        _, candidates, length = found
        i += length

    # 3. verbe, et ce qui le précède (l'objet)
    verb_at = next((j for j in range(i, len(tokens))
                    if {"verbe", "verbe_reference"} & set(tokens[j].tags)), None)
    if verb_at is not None:
        object_tokens = [t for t in tokens[i:verb_at] if "interrogatif" not in t.tags]
        if object_tokens:
            frame["objet"] = " ".join(t.word for t in object_tokens)
        verb_token = tokens[verb_at]
        key = _key(verb_token.word)
        if "verbe" in verb_token.tags:
            frame["verbe"], frame["forme_verbe"] = lex.verbs[key]
            frame["verbe_confirme"] = True
        else:
            frame["verbe"] = lex.reference_verbs[key]
            notes.append(f"« {verb_token.word} » : verbe connu mais non confirmé ({frame['verbe']})")
        rest = tokens[verb_at + 1:]
    else:
        rest = tokens[i:]
        notes.append("aucun verbe reconnu")

    # 4. choisir le temps parmi les candidats : d'abord l'objet, puis vérification
    #    croisée en reconjuguant avec le moteur (le bon temps redonne la phrase)
    if candidates:
        wants_object = frame["objet"] is not None
        matching = [t for t in candidates if lex.engine.tenses[t].object == wants_object] or list(candidates)
        if len(matching) > 1 and frame["sujet"] and frame["verbe_confirme"]:
            observed = _key(" ".join(t.raw for t in tokens))
            regenerated = []
            for tense in matching:
                try:
                    produced = lex.engine.conjugate(frame["verbe"], frame["sujet"], tense, frame["objet"])
                except ConjugationError:
                    continue
                if observed.startswith(_key(produced)):
                    regenerated.append(tense)
            matching = regenerated or matching
        frame["temps"] = matching[0]
        if len(matching) > 1:
            notes.append(f"plusieurs temps possibles : {', '.join(matching)}")
    elif frame["verbe"] and frame["sujet"]:
        if frame.get("forme_verbe") in ("gerondif", "gerondif_objet", "nom_action"):
            # une forme en -ni sans marqueur : le temps ne se déduit pas
            notes.append(f"« {frame['verbe']} » est à la forme en -ni sans marqueur : temps non identifié")
        else:
            frame["temps"] = "past_object" if frame["objet"] else "past"
    elif frame["verbe"] and not frame["sujet"]:
        frame["temps"] = "imperatif_objet" if frame["objet"] else "imperatif"

    # 5. compléments et mot interrogatif
    for token in rest:
        if "interrogatif" in token.tags and (token.index == len(tokens) - 1 or _key(token.word) != "xa"):
            frame["question"] = QUESTION_WORDS[_key(token.word)]
        elif "determinant" in token.tags and frame["complements"]:
            frame["complements"][-1] += f" {token.word}"
        else:
            frame["complements"].append(token.word)

    # 5a. le suffixe du temps (watia, ni ya me) appartient au verbe, pas aux compléments
    suffix = lex.engine.tenses[frame["temps"]].suffix if frame["temps"] else None
    if suffix:
        parts = [_key(w) for w in suffix.split()]
        tail = [_key(w) for w in frame["complements"][-len(parts):]]
        if tail == parts:
            frame["complements"] = frame["complements"][:-len(parts)]

    # 5b. les expressions du lexique en plusieurs mots (koota su, kan dimma)
    merged: list[str] = []
    for word in frame["complements"]:
        if merged and _key(f"{merged[-1]} {word}") in lex.glossary:
            merged[-1] = f"{merged[-1]} {word}"
        else:
            merged.append(word)
    # un mot interrogatif en deux mots (« kan dimma ») n'apparaît qu'une fois regroupé
    kept = []
    for word in merged:
        if _key(word) in QUESTION_WORDS and frame["question"] is None:
            frame["question"] = QUESTION_WORDS[_key(word)]
        else:
            kept.append(word)
    frame["complements"] = kept

    # 6. vérification croisée de la particule
    for token in tokens:
        if token.particle:
            try:
                expected = lex.engine.particle(token.word)
            except ConjugationError:
                continue
            if expected != token.particle:
                notes.append(f"particule inattendue : « {token.raw} » (attendu {expected}{token.word})")

    if frame["sujet"] is None and frame["verbe"] is None:
        raise AnalysisError("aucun sujet ni verbe reconnu dans la phrase")
    return frame, notes


# --- Génération du français -----------------------------------------------------

def _translate(word: str, lex: Lexicon, notes: list[str]) -> str:
    fr = lex.glossary.get(_key(word))
    if fr:
        return fr
    notes.append(f"« {word} » : mot absent du lexique → {UNKNOWN}")
    return UNKNOWN


def to_french(frame: dict, lex: Lexicon, notes: list[str]) -> str:
    complements = [_translate(w, lex, notes) for w in frame["complements"]]
    obj_fr = _translate(frame["objet"], lex, notes) if frame["objet"] else None
    person = frame["personne"] or "2sg"
    subject = SUBJECTS.get(person, UNKNOWN)

    if frame["verbe_confirme"] and frame["temps"] and frame["verbe"] in lex.french:
        try:
            core = conjugate_fr(lex.french[frame["verbe"]], person, frame["temps"], obj_fr)
        except FrenchError as exc:
            notes.append(f"pas de traduction française pour ce temps ({exc}) → {UNKNOWN}")
            core = f"{subject} {UNKNOWN}" + (f" {obj_fr}" if obj_fr else "")
    else:
        if frame["verbe"] and not frame["verbe_confirme"]:
            verb_fr = f"{frame['verbe']} [non confirmé]"
        else:
            if frame["verbe"] and not frame["temps"]:
                notes.append(f"temps non identifié → {UNKNOWN}")
            elif not frame["verbe"]:
                notes.append(f"verbe non reconnu → {UNKNOWN}")
            verb_fr = UNKNOWN
        parts = [subject] if frame["sujet"] else []
        parts.append(verb_fr)
        if obj_fr:
            parts.append(obj_fr)
        core = " ".join(parts)

    phrase = " ".join([core, *complements]).strip()
    if frame["question"]:
        phrase = f"{phrase} {frame['question']}".strip() if frame["question"] != "(question)" else phrase
        return phrase.rstrip(" ?") + " ?"
    return phrase


def collapse_unknowns(text: str) -> str:
    """« [unknown] [unknown] [unknown] » → « [unknown] » : une seule marque par passage."""
    return re.sub(rf"(?:{re.escape(UNKNOWN)}\s*)+", UNKNOWN + " ", text).strip()


# --- Entrée publique ------------------------------------------------------------

def analyze(sentence: str, lex: Lexicon | None = None) -> Analysis:
    """Analyse une proposition. Lève AnalysisError si rien n'y est reconnu."""
    lex = lex or load_lexicon()
    tokens = tag(tokenize(sentence), lex)
    frame, notes = assemble(tokens, lex)
    french = collapse_unknowns(to_french(frame, lex, notes))
    confirmed = bool(frame["verbe_confirme"] and frame["temps"]) and UNKNOWN not in french
    return Analysis(sentence.strip(), french, confirmed, frame, tuple(notes), tuple(tokens))


def _word_by_word(clause: str, lex: Lexicon) -> Analysis:
    """Dernier recours : aucune structure reconnue, on traduit mot à mot ce qui peut l'être."""
    tokens = tag(tokenize(clause), lex)
    notes: list[str] = ["aucune structure de phrase reconnue : traduction mot à mot"]
    words = []
    for t in tokens:
        key = _key(t.word)
        if key in lex.glossary:
            words.append(lex.glossary[key])
        else:
            words.append(UNKNOWN)
            notes.append(f"« {t.raw} » : non reconnu → {UNKNOWN}")
    return Analysis(clause.strip(), collapse_unknowns(" ".join(words)), False, {}, tuple(notes), tuple(tokens))


def analyze_text(text: str, lex: Lexicon | None = None) -> list[Analysis]:
    """Traduit n'importe quel texte, sans jamais échouer.

    Le texte est découpé en phrases, puis en propositions (sur , ; :). Chaque
    proposition est analysée ; si rien n'y est reconnu, elle est traduite mot à mot,
    et tout ce qui n'est pas compris devient [unknown].
    """
    lex = lex or load_lexicon()
    results: list[Analysis] = []
    for sentence in split_sentences(text):
        end = sentence[-1] if sentence[-1] in ".!?" else ""
        parts = CLAUSE_SPLIT.split(sentence.rstrip(".!?").strip())
        clauses = [(parts[i], parts[i + 1] if i + 1 < len(parts) else end) for i in range(0, len(parts), 2)]
        for clause, punct in clauses:
            if not _clean(clause):
                continue
            try:
                a = analyze(clause, lex)
            except AnalysisError:
                a = _word_by_word(clause, lex)
            results.append(Analysis(a.snk, a.fr, a.confirme, a.frame, a.notes, a.tokens, punct))
    return results


def render(analyses: list[Analysis]) -> str:
    """Recompose la traduction d'un texte, avec sa ponctuation."""
    out = ""
    for a in analyses:
        out += a.fr + (a.ponctuation if a.ponctuation in ".!?" else a.ponctuation) + " "
    return re.sub(r"\s+([,;:.!?])", r"\1", out).strip()
